"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[58491],{58491:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/a-beautiful-weapon.png\\"\\n          title=\\"A Beautiful Weapon\\"\\n          author=\\"Keigo Higashino\\"\\n          publisher=\\"RHK (RHM Korea)\\"\\n          publishedDate=\\"2016-08-18\\"\\n          isbn=\\"9788925559834\\"\\n          rating=3\\n          tags=\\"thriller\\"\\n        />\\n</center>\\n\\n## Review\\nSet in the cold world of sports where one cannot survive without being first, it shows the downfall of characters who discarded even human dignity for the ```beauty``` of a gold medal.  \\n<br>\\nIt is based on criticism of doping issues, bioethics, and a success-oriented society.  \\n<br>\\nAt the threshold of death, the athletes realize that the <mark>manipulated gold medals</mark> and trophies they tried to protect with their lives were merely ```junk```.  \\nThe survive\'s final monologue, ```What on earth was I running for?```, seems to well express what the author wanted to convey through this work."}')}}]);